PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/schema/2.0/bricks#>
SELECT ?zone ?sensor ?tsid WHERE {
  ?zone a brick:Zone ; rdfs:label "DataCenter_bot_ZN_6" .
  ?sensor a brick:ElectricPowerSensor ; brick:hasLocation ?zone ; brick:hasProperty brick:LightingElectricPower .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?z ?lbl ?type WHERE {
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?z a ?type .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/2.0/bricks#>
SELECT ?sensor ?class ?tsid WHERE {
  ?sensor a brick:Sensor ; brick:hasLocation "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07" ; a ?class .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid . }
  FILTER(str(?class) != "Sensor")
}

